            id: "luis-gonzaga",
            name: "Saint Aloysius Gonzaga",
            lifespan: "1568–1591",
            role: "Religioso jesuíta",
            rank: "Memória",
            calendarNote: "Calendário Romano Geral — conferir edição",
            bioParagraphs: ["He renounced court life, entered the Society of Jesus, and died while caring for the sick during an epidemic in Rome."],
